        #region 状态机
        private class KrakenStateMachine : EntityStateMachine
        {
            public KrakenStateMachine()
            {
                // Phase 1
                AddState(new HiddenState());

                // Phase 2
                AddState(new AppearState());
                AddState(new IdleState());
                //AddState(new BarrageEyeState());
                //AddState(new FlameEyeState());
                AddState(new RoarState());
                //AddState(new LaserEyeState());
                //AddState(new AbsorbState());
                //AddState(new DrainageState());

                // Phase 3
                //AddState(new SwitchPhase2State());
                //AddState(new CommandRoarState());
                //AddState(new TimeBombState());

                // Extra
                AddState(new StunnedState());
                AddState(new DeathState());
            }
        }
        #endregion

        private static void CheckDeath(Entity entity)
        {
            if (!entity.IsDead)
                return;
            stateMachine.StartState(entity, STATE_DEATH);
        }

        #region 隐藏
        private class HiddenState : EntityStateMachineState
        {
            public HiddenState() : base(STATE_HIDDEN, ANIMATION_STATE_HIDDEN) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                SetTintMultiplier(entity, Color.clear);
                SetShadowAlpha(entity, 0);
                SetInvincible(entity, true);
            }
            public override void OnExit(EntityStateMachine machine, Entity entity)
            {
                base.OnExit(machine, entity);
                SetTintMultiplier(entity, Color.white);
            }
            public override void OnUpdateAI(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateAI(machine, entity);
                // 转阶段
                if (AllTentaclesAreDead(entity))
                {
                    SwitchToPhase2(entity);
                    return;
                }
            }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                CheckDeath(entity);
            }
        }
        #endregion

        #region 出现
        private class AppearState : EntityStateMachineState
        {
            public AppearState() : base(STATE_APPEAR, ANIMATION_STATE_APPEAR) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var substateTimer = stateMachine.GetSubStateTimer(entity);
                substateTimer.ResetSeconds(0.5f);
                SetInvincible(entity, true);
                SetTintMultiplier(entity, Color.white);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var substate = stateMachine.GetSubState(entity);
                var timer = stateMachine.GetSubStateTimer(entity);
                timer.Run(stateMachine.GetSpeed(entity));
                switch (substate)
                {
                    case SUBSTATE_FLOATING:
                        SetShadowAlpha(entity, timer.GetPassedPercentage());
                        if (timer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_OUT);
                            timer.ResetSeconds(1f);
                            PlaySplash(entity);
                        }
                        break;
                    case SUBSTATE_OUT:
                        if (timer.Expired)
                        {
                            stateMachine.StartState(entity, STATE_ROAR);
                        }
                        break;
                }
            }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                CheckDeath(entity);
            }
            public const int SUBSTATE_FLOATING = 0;
            public const int SUBSTATE_OUT = 1;
        }
        #endregion

